gqd(){return"\u0c87\u0cae\u0cc7\u0cb2\u0ccd \u0c85\u0ca5\u0cb5\u0cbe \u0cab\u0ccb\u0ca8\u0ccd \u0cb8\u0c82\u0c96\u0ccd\u0caf\u0cc6 \u0ca8\u0cae\u0cc2\u0ca6\u0cbf\u0cb8\u0cc1\u0cb5\u0cc1\u0ca6\u0cc1 \u0c85\u0c97\u0ca4\u0ccd\u0caf."},
gqb(){return"\u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0cbe\u0ca8\u0ccd\u0caf\u0cb5\u0cbe\u0ca6 \u0c87\u0cae\u0cc7\u0cb2\u0ccd \u0c85\u0ca5\u0cb5\u0cbe 10-\u0c85\u0c82\u0c95\u0cbf\u0caf \u0cab\u0ccb\u0ca8\u0ccd \u0cb8\u0c82\u0c96\u0ccd\u0caf\u0cc6 \u0ca8\u0cae\u0cc2\u0ca6\u0cbf\u0cb8\u0cbf."},
gqg(){return"\u0ca8\u0cbe\u0cb5\u0cc1 \u0ca8\u0cbf\u0cae\u0ccd\u0cae\u0ca8\u0ccd\u0ca8\u0cc1 \u0cb8\u0cc8\u0ca8\u0ccd \u0c87\u0ca8\u0ccd \u0cae\u0cbe\u0ca1\u0cb2\u0cc1 \u0cb8\u0cbe\u0ca7\u0ccd\u0caf\u0cb5\u0cbe\u0c97\u0cb2\u0cbf\u0cb2\u0ccd\u0cb2. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0ca8\u0cbf\u0cae\u0ccd\u0cae \u0cb8\u0c82\u0cb8\u0ccd\u0ca5\u0cc6\u0caf \u0c85\u0ca1\u0ccd\u0cae\u0cbf\u0ca8\u0cbf\u0cb8\u0ccd\u0c9f\u0ccd\u0cb0\u0cc7\u0c9f\u0cb0\u0ccd \u0c85\u0ca8\u0ccd\u0ca8\u0cc1 \u0cb8\u0c82\u0caa\u0cb0\u0ccd\u0c95\u0cbf\u0cb8\u0cbf."},
